<?php
require_once __DIR__ . '/config.php'; require_admin();
$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
    verify_csrf(); $name=trim($_POST['name']??''); $nisn=trim($_POST['nisn']??''); $ttl=trim($_POST['ttl']??''); $gender=trim($_POST['gender']??''); $email=strtolower(trim($_POST['email']??'')); $phone=normalize_phone($_POST['phone']??''); $address=trim($_POST['address']??''); $password=(string)($_POST['password']??'');
    if($name===''||$ttl===''||$gender===''||$email===''||$phone===''||$address===''||strlen($password)<6) $error='Semua data wajib diisi dan password minimal 6 karakter.';
    elseif(!preg_match('/^[0-9]{10}$/',$nisn)) $error='NISN harus berisi tepat 10 angka.';
    elseif(!preg_match('/^62[0-9]{8,14}$/',$phone)) $error='Nomor HP tidak valid.';
    else { $check=mysqli_prepare($koneksi,'SELECT id FROM users WHERE email=? LIMIT 1'); mysqli_stmt_bind_param($check,'s',$email); mysqli_stmt_execute($check); if(mysqli_num_rows(mysqli_stmt_get_result($check))) $error='Email sudah terdaftar.'; else { $hash=password_hash($password,PASSWORD_DEFAULT); $stmt=mysqli_prepare($koneksi,"INSERT INTO users (name,nisn,ttl,gender,email,phone,password_hash,role,address) VALUES (?,?,?,?,?,?,?,'user',?)"); mysqli_stmt_bind_param($stmt,'ssssssss',$name,$nisn,$ttl,$gender,$email,$phone,$hash,$address); if(mysqli_stmt_execute($stmt)){ $userMessage='Halo '.$name.', akun Ujian ASTS Anda berhasil dibuat oleh admin. Silakan login menggunakan email '.$email.' dan password awal yang diberikan admin.'; $userSent=send_whatsapp($phone,$userMessage); notify_admins('User baru ditambahkan admin: '.$name.' ('.$email.').'); set_flash('success',$userSent?'User berhasil ditambahkan dan notifikasi WhatsApp sudah dikirim ke nomor user.':'User berhasil ditambahkan, tetapi notifikasi WhatsApp ke nomor user belum terkirim.'); redirect('admin.php');} $error='Gagal menambah user: '.mysqli_error($koneksi); } }
}
?>
<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Tambah User</title><link rel="stylesheet" href="app.css"></head><body><?php require __DIR__ . '/decor.php'; ?><nav class="nav"><a class="brand" href="admin.php">Ujian ASTS · Admin</a><a href="logout.php">Logout</a></nav><main class="wrap"><div class="card"><h1>Tambah User</h1><?php if($error): ?><div class="flash error"><?=e($error)?></div><?php endif; ?><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><div class="grid"><div><label>Nama</label><input name="name" required></div><div><label>NISN (10 angka)</label><input name="nisn" pattern="[0-9]{10}" maxlength="10" required></div><div><label>TTL</label><input name="ttl" required></div><div><label>Gender</label><select name="gender" required><option value="">-- Pilih --</option><option value="MALE">Laki-laki</option><option value="FEMALE">Perempuan</option></select></div><div><label>Email</label><input type="email" name="email" required></div><div><label>No. HP / WhatsApp</label><input name="phone" placeholder="08123456789" required></div><div><label>Password awal</label><input type="password" name="password" minlength="6" required></div><div><label>Alamat</label><textarea name="address" rows="3" required></textarea></div></div><div class="actions"><button class="primary">Simpan User</button><a class="btn secondary" href="admin.php">Batal</a></div></form></div></main></body></html>
